package com.northstarbank.console.web;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClientResponseException;import org.springframework.web.server.ResponseStatusException;
@ControllerAdvice public class ErrorAdvice{@ExceptionHandler(RestClientResponseException.class)ResponseEntity<Void> tier(RestClientResponseException e){HttpStatusCode status=e.getStatusCode().is4xxClientError()?HttpStatus.NOT_FOUND:HttpStatus.BAD_GATEWAY;return ResponseEntity.status(status).build();}@ExceptionHandler(ResponseStatusException.class)ResponseEntity<Void> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).build();}}
